CREATE OR REPLACE FUNCTION sync_user_note_customer_note() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    IF TG_OP = 'UPDATE' THEN
      IF NEW.note != OLD.note THEN
        NEW.customer_note := NEW.note;
      END IF;
      IF NEW.customer_note != OLD.customer_note THEN
        NEW.note := NEW.customer_note;
      END IF;
    ELSE
      -- INSERT: set both columns to the same value (note preferred)
      NEW.note := COALESCE(NEW.note, NEW.customer_note);
      NEW.customer_note := NEW.note;
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
